:CRTDisplay a owl:Class ;
    rdfs:label "CRT display"@en ;
    rdfs:comment "A type of display device."@en ;
    rdfs:subClassOf :DisplayDevice .

:CloudDelivery a :DistributionMethod ;
    rdfs:label "Cloud Delivery"@en ;
    rdfs:comment "Distribution or access in which game execution or delivery is provided through cloud infrastructure."@en ;
    skos:prefLabel "Cloud Delivery"@en .

:Competitive a :MultiplayerStyle ;
    rdfs:label "Competitive"@en ;
    rdfs:comment "A named multiplayer style value: Competitive."@en ;
    skos:prefLabel "Competitive"@en .

:ComputerMonitor a owl:Class ;
    rdfs:label "Computer Monitor"@en ;
    rdfs:comment "A type of display device."@en ;
    rdfs:subClassOf :DisplayDevice .

:ComputerSpace a :VideoGame ;
    rdfs:label "Computer Space"@en ;
    prov:wasInfluencedBy :Spacewar .

:Cooperative a :MultiplayerStyle ;
    rdfs:label "Cooperative"@en ;
    rdfs:comment "A named multiplayer style value: Cooperative."@en ;
    skos:prefLabel "Cooperative"@en .

:CoreGame a owl:Class ;
    rdfs:label "Core Game"@en ;
    rdfs:comment "A type of video game."@en ;
    rdfs:subClassOf :VideoGame .

:DVD a owl:Class ;
    rdfs:label "DVD"@en ;
    rdfs:comment "A type of optical disc."@en ;
    rdfs:subClassOf :OpticalDisc .

:DancePad a owl:Class ;
    rdfs:label "Dance Pad"@en ;
    rdfs:comment "A specialized game controller operated primarily with the feet."@en ;
    rdfs:subClassOf :GameController .

:DeveloperRole a prov:Role ;
    rdfs:label "Developer Role"@en ;
    rdfs:comment "A PROV role used to qualify an organization's participation as a developer."@en .

:DigitalDownload a :DistributionMethod ;
    rdfs:label "Digital Download"@en ;
    rdfs:comment "Distribution by downloading a digital game package."@en ;
    skos:prefLabel "Digital Download"@en .

:DistributorRole a prov:Role ;
    rdfs:label "Distributor Role"@en ;
    rdfs:comment "A PROV role used to qualify an organization's participation as a distributor."@en .

:DownloadableContent a owl:Class ;
    rdfs:label "Downloadable Content"@en ;
    rdfs:comment "A type of game extension."@en ;
    rdfs:subClassOf :GameExtension .

:ESRB a :RatingSystem ;
    rdfs:label "ESRB"@en ;
    rdfs:comment "A named rating system value: ESRB."@en ;
    skos:prefLabel "ESRB"@en ;
    :appliesInRegion :UnitedStates .

:EdutainmentGame a owl:Class ;
    rdfs:label "Edutainment Game"@en ;
    rdfs:comment "An educational game emphasizing entertainment and accessible learning activities."@en ;
    rdfs:subClassOf :EducationalGame .

:EsportsEvent a owl:Class ;
    rdfs:label "Esports Event"@en ;
    rdfs:comment "A class that is a subtype of competitive context and prov:Activity."@en ;
    rdfs:subClassOf prov:Activity,
        :CompetitiveContext .

:ExpansionPack a owl:Class ;
    rdfs:label "Expansion Pack"@en ;
    rdfs:comment "A type of game extension."@en ;
    rdfs:subClassOf :GameExtension .

:FitnessGame a owl:Class ;
    rdfs:label "Fitness Game"@en ;
    rdfs:comment "A serious game that incorporates significant physical exercise or fitness-oriented activity."@en ;
    rdfs:subClassOf :SeriousGame .

:FlashMemoryCard a owl:Class ;
    rdfs:label "Flash Memory Card"@en ;
    rdfs:comment "A type of physical media format."@en ;
    rdfs:subClassOf :PhysicalMediaFormat .

:FloppyDisk a owl:Class ;
    rdfs:label "Floppy Disk"@en ;
    rdfs:comment "A type of physical media format."@en ;
    rdfs:subClassOf :PhysicalMediaFormat .

:GameBoy a :HandheldConsole ;
    rdfs:label "Game Boy"@en ;
    :hasPlatformHolder :Nintendo .

:Gamepad a owl:Class ;
    rdfs:label "Gamepad"@en ;
    rdfs:comment "A handheld game controller with buttons, directional controls, or analog inputs."@en ;
    rdfs:subClassOf :GameController .

:GamesAsAService a :MonetizationModel ;
    rdfs:label "Games as a Service"@en ;
    rdfs:comment "A monetization model in which a game is operated and updated as an ongoing service."@en ;
    skos:prefLabel "Games as a Service"@en .

:HapticFeedbackCapability a :FeedbackCapability ;
    rdfs:label "Haptic Feedback Capability"@en ;
    rdfs:comment "A named feedback capability representing haptic or tactile feedback."@en .

:Headphones a owl:Class ;
    rdfs:label "Headphones"@en ;
    rdfs:comment "A type of output device."@en ;
    rdfs:subClassOf :OutputDevice .

:HeadsUpDisplay a owl:Class ;
    rdfs:label "Heads-up Display"@en ;
    rdfs:comment "An on-screen user interface that presents gameplay information over the rendered game view."@en ;
    rdfs:subClassOf :UserInterface .

:HyperCasualGame a owl:Class ;
    rdfs:label "Hyper-casual Game"@en ;
    rdfs:comment "A casual game characterized by especially simple rules and short, readily replayable play sessions."@en ;
    rdfs:subClassOf :CasualGame .

:InternetOnline a :MultiplayerConnectivityMode ;
    rdfs:label "Internet/online"@en ;
    rdfs:comment "A named multiplayer connectivity mode value: Internet/online."@en ;
    skos:prefLabel "Internet/online"@en .

:Joystick a owl:Class ;
    rdfs:label "Joystick"@en ;
    rdfs:comment "A game controller centered on a movable stick for directional or analog input."@en ;
    rdfs:subClassOf :GameController .

:Keyboard a owl:Class ;
    rdfs:label "Keyboard"@en ;
    rdfs:comment "A type of input device."@en ;
    rdfs:subClassOf :InputDevice .

:LCDDisplay a owl:Class ;
    rdfs:label "LCD display"@en ;
    rdfs:comment "A type of display device."@en ;
    rdfs:subClassOf :DisplayDevice .

:LightGun a owl:Class ;
    rdfs:label "Light Gun"@en ;
    rdfs:comment "A game controller designed for aiming at or interacting with a display."@en ;
    rdfs:subClassOf :GameController .

:LocalNetwork a :MultiplayerConnectivityMode ;
    rdfs:label "Local Network"@en ;
    rdfs:comment "A named multiplayer connectivity mode value: Local Network."@en ;
    skos:prefLabel "Local Network"@en .

:LocalSameDevice a :MultiplayerConnectivityMode ;
    rdfs:label "Local same-device"@en ;
    rdfs:comment "A named multiplayer connectivity mode value: Local same-device."@en ;
    skos:prefLabel "Local same-device"@en .

:MagnavoxOdyssey a :HomeConsole ;
    rdfs:label "Magnavox Odyssey"@en .

:MagneticTape a owl:Class ;
    rdfs:label "Magnetic Tape"@en ;
    rdfs:comment "A type of physical media format."@en ;
    rdfs:subClassOf :PhysicalMediaFormat .

:MarketerRole a prov:Role ;
    rdfs:label "Marketer Role"@en ;
    rdfs:comment "A PROV role used when an organization participates in promoting or marketing a game or release."@en .

:MassivelyMultiplayer a :MultiplayerStyle ;
    rdfs:label "Massively Multiplayer"@en ;
    rdfs:comment "A named multiplayer style value: Massively Multiplayer."@en ;
    skos:prefLabel "Massively Multiplayer"@en .

:MobilePlatform a owl:Class ;
    rdfs:label "Mobile Platform"@en ;
    rdfs:comment "A type of platform."@en ;
    rdfs:subClassOf :Platform .

:MotionSensor a owl:Class ;
    rdfs:label "Motion Sensor"@en ;
    rdfs:comment "A type of input device."@en ;
    rdfs:subClassOf :InputDevice .

:Mouse a owl:Class ;
    rdfs:label "Mouse"@en ;
    rdfs:comment "A type of input device."@en ;
    rdfs:subClassOf :InputDevice .

:Multiplayer a :GameMode ;
    rdfs:label "Multiplayer"@en ;
    rdfs:comment "A named game mode value: Multiplayer."@en ;
    skos:prefLabel "Multiplayer"@en .

:Newsgame a owl:Class ;
    rdfs:label "Newsgame"@en ;
    rdfs:comment "A serious game designed to communicate or explore a news-related, political, or advocacy-oriented subject."@en ;
    rdfs:subClassOf :SeriousGame .

:NonPlayerCharacter a owl:Class ;
    rdfs:label "Non Player Character"@en ;
    rdfs:comment "A type of character."@en ;
    rdfs:subClassOf :Character .

:PEGI a :RatingSystem ;
    rdfs:label "PEGI"@en ;
    rdfs:comment "A named rating system value: PEGI."@en ;
    skos:prefLabel "PEGI"@en ;
    :appliesInRegion :UnitedKingdom .

:Passage a :ArtGame ;
    rdfs:label "Passage"@en .

:PersonalComputerPlatform a owl:Class ;
    rdfs:label "Personal Computer Platform"@en ;
    rdfs:comment "A type of platform."@en ;
    rdfs:subClassOf :Platform .

:PhysicalMediaDistribution a :DistributionMethod ;
    rdfs:label "Physical Media Distribution"@en ;
    rdfs:comment "Distribution through a physical carrier such as a cartridge, disc, tape, or memory card."@en ;
    skos:prefLabel "Physical Media Distribution"@en .

:PlayStation2 a :HomeConsole ;
    rdfs:label "PlayStation 2"@en ;
    :backwardCompatibleWith :PlayStation .

:PlayStationNow a :CloudGamingService ;
    rdfs:label "PlayStation Now"@en .

:PlayerCharacter a owl:Class ;
    rdfs:label "Player Character"@en ;
    rdfs:comment "A type of character."@en ;
    rdfs:subClassOf :Character .

:Pong a :VideoGame ;
    rdfs:label "Pong"@en .

:Projector a owl:Class ;
    rdfs:label "Projector"@en ;
    rdfs:comment "A type of display device."@en ;
    rdfs:subClassOf :DisplayDevice .

:PublisherRole a prov:Role ;
    rdfs:label "Publisher Role"@en ;
    rdfs:comment "A PROV role used to qualify an organization's participation as a publisher."@en .

:ROMCartridge a owl:Class ;
    rdfs:label "ROM cartridge"@en ;
    rdfs:comment "A type of physical media format."@en ;
    rdfs:subClassOf :PhysicalMediaFormat .

:RacingWheel a owl:Class ;
    rdfs:label "Racing Wheel"@en ;
    rdfs:comment "A game controller designed to simulate steering in driving games."@en ;
    rdfs:subClassOf :GameController .

:RetailerRole a prov:Role ;
    rdfs:label "Retailer Role"@en ;
    rdfs:comment "A PROV role used when an organization participates in bringing a game or release to consumers as a retailer."@en .

:Review a owl:Class ;
    rdfs:label "Review"@en ;
    rdfs:comment "A review of a GameRelease. Use schema:itemReviewed for the reviewed release, schema:reviewBody for review text, schema:reviewRating with schema:ratingValue for a structured score, and dcterms:source for source citation when applicable."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty schema:itemReviewed ;
            owl:someValuesFrom :GameRelease ],
        prov:Entity,
        schema:Review .

:SinglePlayer a :GameMode ;
    rdfs:label "Single Player"@en ;
    rdfs:comment "A named game mode value: Single Player."@en ;
    skos:prefLabel "Single Player"@en .

:Speaker a owl:Class ;
    rdfs:label "Speaker"@en ;
    rdfs:comment "A type of output device."@en ;
    rdfs:subClassOf :OutputDevice .

:TeamBased a :MultiplayerStyle ;
    rdfs:label "Team Based"@en ;
    rdfs:comment "A named multiplayer style value: Team Based."@en ;
    skos:prefLabel "Team Based"@en .

:Tetris a :CasualGame ;
    rdfs:label "Tetris"@en .

:TheOregonTrail a :EducationalGame ;
    rdfs:label "The Oregon Trail"@en .

:Touchscreen a owl:Class ;
    rdfs:label "Touchscreen"@en ;
    rdfs:comment "A combined display and touch-sensitive input device; it can therefore function as both an InputDevice and a DisplayDevice."@en ;
    rdfs:subClassOf :DisplayDevice,
        :InputDevice .

:USK a :RatingSystem ;
    rdfs:label "USK"@en ;
    rdfs:comment "A named rating system value: USK."@en ;
    skos:prefLabel "USK"@en ;
    :appliesInRegion :Germany .

:VRController a owl:Class ;
    rdfs:label "VR controller"@en ;
    rdfs:comment "A class that is a subtype of vr input device and game controller."@en ;
    rdfs:subClassOf :GameController .

:VRHeadset a owl:Class ;
    rdfs:label "VR headset"@en ;
    rdfs:comment "A class that is a subtype of display device and vr output device."@en ;
    rdfs:subClassOf :DisplayDevice .

:VirtualRealityPlatform a owl:Class ;
    rdfs:label "Virtual Reality Platform"@en ;
    rdfs:comment "A type of platform."@en ;
    rdfs:subClassOf :Platform .

:VisualFeedbackCapability a :FeedbackCapability ;
    rdfs:label "Visual Feedback Capability"@en ;
    rdfs:comment "A named feedback capability representing visual feedback."@en .

:Wii a :HomeConsole ;
    rdfs:label "Wii"@en ;
    :backwardCompatibleWith :GameCube .

:WiiFit a :SeriousGame ;
    rdfs:label "Wii Fit"@en .

:XboxCloudGaming a :CloudGamingService ;
    rdfs:label "Xbox Cloud Gaming"@en .

:ZeroPlayer a :GameMode ;
    rdfs:label "Zero Player"@en ;
    rdfs:comment "A named game mode value: Zero Player."@en ;
    skos:prefLabel "Zero Player"@en .

:administeredBy a owl:ObjectProperty ;
    rdfs:label "administered by"@en ;
    rdfs:comment "Identifies the rating authority that administers a RatingSystem."@en ;
    rdfs:domain :RatingSystem ;
    rdfs:range :RatingAuthority .

:appliesInRegion a owl:ObjectProperty ;
    rdfs:label "applies in region"@en ;
    rdfs:comment "Identifies a Region in which a RatingSystem applies."@en ;
    rdfs:domain :RatingSystem ;
    rdfs:range :Region .

:associatedWithHistoricalPeriod a owl:ObjectProperty ;
    rdfs:label "associated with historical period"@en ;
    rdfs:comment "Associates a resource or contextualized label with a HistoricalPeriod."@en ;
    rdfs:domain rdfs:Resource ;
    rdfs:range :HistoricalPeriod ;
    rdfs:subPropertyOf dcterms:temporal .

:associatedWithRegion a owl:ObjectProperty ;
    rdfs:label "associated with region"@en ;
    rdfs:comment "Associates a resource or contextualized label with a Region."@en ;
    rdfs:domain rdfs:Resource ;
    rdfs:range :Region ;
    rdfs:subPropertyOf dcterms:spatial .

:availableInRegion a owl:ObjectProperty ;
    rdfs:label "available in region"@en ;
    rdfs:comment "Indicates a Region in which a GameRelease is available."@en ;
    rdfs:domain :GameRelease ;
    rdfs:range :Region .

:backwardCompatibleWith a owl:ObjectProperty ;
    rdfs:label "backward compatible with"@en ;
    rdfs:comment "Indicates an older Platform whose software a newer Platform can run or otherwise support through backward compatibility."@en ;
    rdfs:domain :Platform ;
    rdfs:range :Platform .

:conversionOf a owl:ObjectProperty ;
    rdfs:label "conversion of"@en ;
    rdfs:comment "Identifies the earlier GameResource from which this GameResource was converted; conversion is a form of PROV derivation."@en ;
    rdfs:domain :GameResource ;
    rdfs:range :GameResource ;
    rdfs:subPropertyOf prov:wasDerivedFrom .

:developedBy a owl:ObjectProperty ;
    rdfs:label "developed by"@en ;
    rdfs:comment "Identifies an Organization that developed a VideoGame or GameRelease; use :DeveloperRole in a qualified PROV association when the role needs explicit qualification."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( :VideoGame :GameRelease ) ] ;
    rdfs:range :Organization ;
    rdfs:subPropertyOf :hasParticipatingOrganization,
        schema:creator .

:developedWithEngine a owl:ObjectProperty ;
    rdfs:label "developed with engine"@en ;
    rdfs:comment "Identifies the GameEngine used to develop a VideoGame or GameRelease."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( :VideoGame :GameRelease ) ] ;
    rdfs:range :GameEngine .

:distributedBy a owl:ObjectProperty ;
    rdfs:label "distributed by"@en ;
    rdfs:comment "Identifies an Organization that distributed a VideoGame or GameRelease; use :DistributorRole in a qualified PROV association when the role needs explicit qualification."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( :VideoGame :GameRelease ) ] ;
    rdfs:range :Organization ;
    rdfs:subPropertyOf :hasParticipatingOrganization .

:distributedOnMediaFormat a owl:ObjectProperty ;
    rdfs:label "distributed on media format"@en ;
    rdfs:comment "Identifies a MediaFormat on which a GameRelease was distributed."@en ;
    rdfs:domain :GameRelease ;
    rdfs:range :MediaFormat ;
    rdfs:subPropertyOf :usesMediaFormat .

:distributedVia a owl:ObjectProperty ;
    rdfs:label "distributed via"@en ;
    rdfs:comment "Identifies the DistributionMethod used for a GameRelease."@en ;
    rdfs:domain :GameRelease ;
    rdfs:range :DistributionMethod .

:emulatableOnPlatform a owl:ObjectProperty ;
    rdfs:label "emulatable on platform"@en ;
    rdfs:comment "Indicates a Platform on which a VideoGame or GameRelease can be run through emulation."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( :VideoGame :GameRelease ) ] ;
    rdfs:range :Platform .

:engineSupportsPlatform a owl:ObjectProperty ;
    rdfs:label "engine supports platform"@en ;
    rdfs:comment "Indicates a Platform supported by a GameEngine."@en ;
    rdfs:domain :GameEngine ;
    rdfs:range :Platform .

:exclusiveToPlatformHolder a owl:ObjectProperty ;
    rdfs:label "exclusive to platform holder"@en ;
    rdfs:comment "Identifies the Organization holding the platform to which a GameRelease is exclusive. This relation can be inferred from :exclusiveToPlatform followed by :hasPlatformHolder."@en ;
    rdfs:domain :GameRelease ;
    rdfs:range :Organization ;
    owl:propertyChainAxiom ( :exclusiveToPlatform :hasPlatformHolder ) .

:featuresGame a owl:ObjectProperty ;
    rdfs:label "features game"@en ;
    rdfs:comment "Identifies a VideoGame featured in a CompetitiveContext."@en ;
    rdfs:domain :CompetitiveContext ;
    rdfs:range :VideoGame ;
    owl:propertyChainAxiom ( :featuresGameRelease :releaseOf ) .

:hasAgeCategory a owl:ObjectProperty ;
    rdfs:label "has age category"@en ;
    rdfs:comment "Associates a ContentRating with its age-category concept."@en ;
    rdfs:domain :ContentRating ;
    rdfs:range :AgeCategory .

:hasCharacter a owl:ObjectProperty ;
    rdfs:label "has character"@en ;
    rdfs:comment "Associates a VideoGame with a Character appearing in the game."@en ;
    rdfs:domain :VideoGame ;
    rdfs:range :Character .

:hasCompetitor a owl:ObjectProperty ;
    rdfs:label "has competitor"@en ;
    rdfs:comment "Identifies an agent competing in a CompetitiveContext."@en ;
    rdfs:domain :CompetitiveContext ;
    rdfs:range prov:Agent .

:hasContentDescriptor a owl:ObjectProperty ;
    rdfs:label "has content descriptor"@en ;
    rdfs:comment "Associates a ContentRating with a content-descriptor concept."@en ;
    rdfs:domain :ContentRating ;
    rdfs:range :ContentDescriptor .

:hasContentRating a owl:ObjectProperty ;
    rdfs:label "has content rating"@en ;
    rdfs:comment "Associates a GameRelease with an assigned ContentRating."@en ;
    rdfs:domain :GameRelease ;
    rdfs:range :ContentRating .

:hasGameMode a owl:ObjectProperty ;
    rdfs:label "has game mode"@en ;
    rdfs:comment "Associates a VideoGame or GameRelease with a supported GameMode."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( :VideoGame :GameRelease ) ] ;
    rdfs:range :GameMode .

:hasGameplayMechanic a owl:ObjectProperty ;
    rdfs:label "has gameplay mechanic"@en ;
    rdfs:comment "Associates a VideoGame with a GameplayMechanic."@en ;
    rdfs:domain :VideoGame ;
    rdfs:range :GameplayMechanic .

:hasGenre a owl:ObjectProperty ;
    rdfs:label "has genre"@en ;
