        owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ;
        owl:onClass vg:Cl_VideoGame
    ] .

vg:Cl_GainEvent rdfs:subClassOf
    [ a owl:Restriction ;
        owl:onProperty vg:op_hasParticipation ;
        owl:someValuesFrom [
            a owl:Class ;
            owl:intersectionOf (
                vg:Cl_Participation
                [ a owl:Restriction ;
                    owl:onProperty vg:op_playsRole ;
                    owl:someValuesFrom vg:Cl_PlayerRole
                ]
            )
        ]
    ],
    [ a owl:Restriction ;
        owl:onProperty vg:op_hasParticipation ;
