vg:Cl_LoseEvent rdfs:subClassOf
    [ a owl:Restriction ;
        owl:onProperty vg:op_hasParticipation ;
        owl:someValuesFrom [
            a owl:Class ;
            owl:intersectionOf (
                vg:Cl_Participation
                [ a owl:Restriction ;
                    owl:onProperty vg:op_playsRole ;
                    owl:someValuesFrom vg:Cl_PlayerRole
                ]
            )
        ]
    ],
    [ a owl:Restriction ;
        owl:onProperty vg:op_hasParticipation ;
        owl:someValuesFrom [
            a owl:Class ;
            owl:intersectionOf (
                vg:Cl_Participation
                [ a owl:Restriction ;
                    owl:onProperty vg:op_playsRole ;
                    owl:someValuesFrom vg:Cl_AvatarRole
                ]
