    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty vg:modifiesResource ;
            owl:someValuesFrom vg:GameResource ],
        vg:GameExtension .

vg:Nintendo a owl:NamedIndividual,
        vg:Organization ;
    rdfs:label "Nintendo"@en .

vg:Person a owl:Class ;
    rdfs:subClassOf vg:Agent .

vg:Port a owl:Class ;
    rdfs:label "Port"@en ;
    rdfs:comment "A game release adapted to run on a platform or technical environment different from an earlier release."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty vg:portOf ;
            owl:someValuesFrom vg:GameRelease ],
        vg:GameRelease .

vg:Remake a owl:Class ;
    rdfs:label "Remake"@en ;
    rdfs:comment "A game release that recreates an earlier game release as a new derived release."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty vg:remakeOf ;
            owl:someValuesFrom vg:GameRelease ],
        vg:GameRelease .

vg:Remaster a owl:Class ;
    rdfs:label "Remaster"@en ;
    rdfs:comment "A game release derived from an earlier release with revised presentation or technical treatment while substantially preserving the original game."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty vg:remasterOf ;
            owl:someValuesFrom vg:GameRelease ],
        vg:GameRelease .

vg:Spacewar a owl:NamedIndividual,
        vg:VideoGame ;
    rdfs:label "Spacewar!"@en .

vg:accessibleViaOnlineService a owl:ObjectProperty ;
    rdfs:label "accessible via online service"@en ;
    rdfs:comment "Indicates an online service through which a GameResource can be accessed."@en ;
    rdfs:domain vg:GameResource .

vg:associatedWithGame a owl:ObjectProperty ;
    rdfs:label "associated with game"@en ;
    rdfs:comment "Links game-related content to the VideoGame with which it is associated. For a GameExtension that extends a GameRelease, the association can be inferred through :extendsResource followed by :releaseOf."@en ;
    rdfs:range vg:VideoGame ;
    owl:propertyChainAxiom ( vg:extendsResource vg:releaseOf ) .

vg:engineSupportsPlatform a owl:ObjectProperty ;
    rdfs:label "engine supports platform"@en ;
    rdfs:comment "Indicates a Platform supported by a GameEngine."@en ;
    rdfs:domain vg:GameEngine ;
    rdfs:range vg:Platform .

vg:hasCharacter a owl:ObjectProperty ;
    rdfs:label "has character"@en ;
    rdfs:comment "Associates a VideoGame with a Character appearing in the game."@en ;
    rdfs:domain vg:VideoGame ;
    rdfs:range vg:Character .

vg:hasContentRating a owl:ObjectProperty ;
    rdfs:label "has content rating"@en ;
    rdfs:comment "Associates a GameRelease with an assigned ContentRating."@en ;
    rdfs:domain vg:GameRelease ;
    rdfs:range vg:ContentRating .

vg:intendedForPlatform a owl:ObjectProperty ;
    rdfs:label "intended for platform"@en ;
    rdfs:comment "Indicates the Platform for which a VideoGame or GameRelease was originally or intentionally designed."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( vg:GameRelease vg:VideoGame ) ] ;
    rdfs:range vg:Platform ;
    rdfs:subPropertyOf schema:gamePlatform .

vg:issuedByRatingSystem a owl:ObjectProperty ;
    rdfs:label "issued by rating system"@en ;
    rdfs:comment "Identifies the RatingSystem that issued a ContentRating."@en ;
    rdfs:domain vg:ContentRating .

vg:modifiesResource a owl:ObjectProperty ;
    rdfs:label "modifies resource"@en ;
    rdfs:comment "Identifies the GameResource modified by a Mod. Because Mod is a GameExtension, this relation specializes :extendsResource."@en ;
    rdfs:domain vg:Mod ;
    rdfs:range vg:GameResource ;
    rdfs:subPropertyOf vg:extendsResource .

vg:portOf a owl:ObjectProperty ;
    rdfs:label "port of"@en ;
    rdfs:comment "Identifies the earlier GameRelease from which a Port was derived."@en ;
    rdfs:domain vg:Port ;
    rdfs:range vg:GameRelease ;
    rdfs:subPropertyOf prov:wasDerivedFrom .

vg:providesFeedbackCapability a owl:ObjectProperty ;
    rdfs:label "provides feedback capability"@en ;
    rdfs:comment "Identifies a FeedbackCapability provided by a resource, such as visual, audio, or haptic feedback."@en .

vg:remakeOf a owl:ObjectProperty ;
    rdfs:label "remake of"@en ;
    rdfs:comment "Identifies the earlier GameRelease from which a Remake was derived."@en ;
    rdfs:domain vg:Remake ;
    rdfs:range vg:GameRelease ;
    rdfs:subPropertyOf prov:wasDerivedFrom .

vg:remasterOf a owl:ObjectProperty ;
    rdfs:label "remaster of"@en ;
    rdfs:comment "Identifies the earlier GameRelease from which a Remaster was derived."@en ;
    rdfs:domain vg:Remaster ;
    rdfs:range vg:GameRelease ;
    rdfs:subPropertyOf prov:wasDerivedFrom .

vg:Agent a owl:Class ;
    owl:disjointWith vg:Genre .

vg:Assessment a owl:Class ;
    owl:disjointWith vg:Genre .

vg:CloudGamingService a owl:Class ;
    rdfs:label "Cloud Gaming Service"@en ;
    rdfs:comment "A cloud gaming service that also functions as a playable platform: game execution is provided remotely and accessed through an online service."@en ;
    rdfs:subClassOf vg:Platform .

vg:MagneticTape a owl:Class ;
    rdfs:label "Magnetic Tape"@en ;
    rdfs:comment "A type of physical media format."@en ;
    rdfs:subClassOf vg:PhysicalMediaFormat ;
    owl:disjointWith vg:OpticalDisc,
        vg:ROMCartridge .

vg:UserInterface a owl:Class ;
    rdfs:label "User Interface"@en ;
    rdfs:comment "An interface through which a player receives game state information or interacts with a video game."@en .

vg:administeredBy a owl:ObjectProperty ;
    rdfs:label "administered by"@en ;
    rdfs:comment "Identifies the rating authority that administers a RatingSystem."@en ;
    rdfs:range vg:RatingAuthority .

vg:availableOnPlatform a owl:ObjectProperty ;
    rdfs:label "available on platform"@en ;
    rdfs:comment "Indicates a Platform on which a GameRelease is available."@en ;
    rdfs:domain vg:GameRelease ;
    rdfs:range vg:Platform ;
    rdfs:subPropertyOf schema:gamePlatform .

vg:releaseOf a owl:ObjectProperty ;
    rdfs:label "release of"@en ;
    rdfs:comment "Links a particular GameRelease to the VideoGame work that it releases."@en ;
    rdfs:domain vg:GameRelease ;
    rdfs:range vg:VideoGame .

vg:supportsOutputDevice a owl:ObjectProperty ;
    rdfs:label "supports output device"@en ;
    rdfs:comment "Identifies an OutputDevice through which a VideoGame or GameRelease can present output."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( vg:GameRelease vg:VideoGame ) ] ;
    rdfs:range vg:OutputDevice .

schema:gamePlatform a owl:ObjectProperty .

vg:Character a owl:Class ;
    rdfs:label "Character"@en ;
    rdfs:comment "A character appearing in a video game."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty [ owl:inverseOf vg:hasCharacter ] ;
            owl:someValuesFrom vg:VideoGame ] ;
    owl:disjointWith vg:GameplayEvent,
        vg:Genre,
        vg:MediaFormat,
        vg:Platform,
        vg:VideoGame .

vg:Device a owl:Class ;
    rdfs:label "Device"@en ;
    rdfs:comment "A physical or virtual device used for game input or output."@en ;
    owl:disjointWith vg:GameEngine,
        vg:GameResource,
        vg:Genre,
        vg:Review .

vg:RatingAuthority a owl:Class ;
    rdfs:label "Rating Authority"@en ;
    rdfs:comment "An organization that administers a content-rating system."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:minCardinality "1"^^xsd:nonNegativeInteger ;
            owl:onProperty [ owl:inverseOf vg:administeredBy ] ],
        vg:Organization .

vg:Review a owl:Class ;
    rdfs:label "Review"@en ;
    rdfs:comment "A review of a GameRelease. Use schema:itemReviewed for the reviewed release, schema:reviewBody for review text, schema:reviewRating with schema:ratingValue for a structured score, and dcterms:source for source citation when applicable."@en ;
    rdfs:subClassOf vg:Assessment .

vg:extendsResource a owl:ObjectProperty ;
    rdfs:label "extends resource"@en ;
    rdfs:comment "Identifies the GameResource extended by a GameExtension."@en ;
    rdfs:domain vg:GameExtension ;
    rdfs:range vg:GameResource .

vg:hasParticipatingOrganization a owl:ObjectProperty ;
    rdfs:label "has participating organization"@en ;
    rdfs:comment "Relates a VideoGame or GameRelease to an Organization participating in its development, publication, or distribution."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( vg:GameRelease vg:VideoGame ) ] ;
    rdfs:range vg:Organization .

vg:usesMediaFormat a owl:ObjectProperty ;
    rdfs:label "uses media format"@en ;
    rdfs:comment "Identifies a MediaFormat used to distribute or install a GameRelease."@en ;
    rdfs:domain vg:GameRelease ;
    rdfs:range vg:MediaFormat .

prov:wasDerivedFrom a owl:ObjectProperty .

vg:GameEngine a owl:Class ;
    rdfs:label "Game Engine"@en ;
    rdfs:comment "Software used to develop or run a video game or game release."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty vg:engineSupportsPlatform ;
            owl:someValuesFrom vg:Platform ] ;
    owl:disjointWith vg:GameResource,
        vg:Genre .

vg:GameExtension a owl:Class ;
    rdfs:label "Game Extension"@en ;
    rdfs:comment "A game-related creative resource that extends another GameResource, such as an expansion, downloadable content, or mod. Use dcterms:creator with a prov:Agent when creator attribution is recorded."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty vg:associatedWithGame ;
            owl:someValuesFrom vg:VideoGame ],
        [ a owl:Restriction ;
            owl:onProperty vg:extendsResource ;
            owl:someValuesFrom vg:GameResource ],
        vg:GameResource .

vg:ROMCartridge a owl:Class ;
    rdfs:label "ROM cartridge"@en ;
    rdfs:comment "A type of physical media format."@en ;
    rdfs:subClassOf vg:PhysicalMediaFormat .

vg:supportsInputDevice a owl:ObjectProperty ;
    rdfs:label "supports input device"@en ;
    rdfs:comment "Identifies an InputDevice supported by a VideoGame or GameRelease."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( vg:GameRelease vg:VideoGame ) ] ;
    rdfs:range vg:InputDevice .

vg:HomeConsole a owl:Class ;
    rdfs:label "Home Console"@en ;
    rdfs:comment "A type of platform."@en ;
    rdfs:subClassOf vg:Platform .

vg:OpticalDisc a owl:Class ;
    rdfs:label "Optical Disc"@en ;
    rdfs:comment "A type of physical media format."@en ;
    rdfs:subClassOf vg:PhysicalMediaFormat ;
    owl:disjointWith vg:ROMCartridge .

vg:SeriousGame a owl:Class ;
    rdfs:label "Serious Game"@en ;
    rdfs:comment "A type of video game."@en ;
    rdfs:subClassOf vg:VideoGame .

vg:ContentRating a owl:Class ;
    rdfs:label "Content Rating"@en ;
    rdfs:comment "A provenance-capable content-rating assignment for a GameRelease that is issued by at least one RatingSystem; it may also carry a rating code, age category, content descriptors, and source metadata via dcterms:source."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty vg:issuedByRatingSystem ;
            owl:someValuesFrom [ a owl:Restriction ;
                    owl:onProperty vg:administeredBy ;
                    owl:someValuesFrom vg:RatingAuthority ] ],
        [ a owl:Restriction ;
            owl:onClass vg:GameRelease ;
            owl:onProperty [ owl:inverseOf vg:hasContentRating ] ;
            owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ],
        vg:Assessment ;
    owl:disjointWith vg:Device,
        vg:GameEngine,
        vg:GameResource,
        vg:Review .

vg:GameController a owl:Class ;
    rdfs:label "Game Controller"@en ;
    rdfs:comment "An input device designed primarily for controlling gameplay."@en ;
    rdfs:subClassOf vg:InputDevice ;
    skos:altLabel "Controller"@en .

vg:OutputDevice a owl:Class ;
    rdfs:label "Output Device"@en ;
    rdfs:comment "A device used to present visual, audio, haptic, or other game output."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:minCardinality "1"^^xsd:nonNegativeInteger ;
            owl:onProperty vg:providesFeedbackCapability ],
        vg:Device .

vg:PhysicalMediaFormat a owl:Class ;
    rdfs:label "Physical Media Format"@en ;
    rdfs:comment "A type of media format."@en ;
    rdfs:subClassOf vg:MediaFormat .

vg:DisplayDevice a owl:Class ;
    rdfs:label "Display Device"@en ;
    rdfs:comment "A type of output device."@en ;
    rdfs:subClassOf vg:OutputDevice .

vg:Genre a owl:Class ;
    owl:disjointWith vg:MediaFormat,
        vg:Platform,
        vg:UserInterface,
        vg:VideoGame .

vg:MediaFormat a owl:Class ;
    rdfs:label "Media Format"@en ;
    rdfs:comment "A physical or digital format used to distribute or install a game release."@en ;
    owl:disjointWith vg:Platform,
        vg:VideoGame .

vg:Organization a owl:Class ;
    rdfs:label "Organization"@en ;
    rdfs:comment "An organization participating in the video-game ecosystem."@en ;
    rdfs:subClassOf vg:Agent ;
    owl:disjointWith vg:Person .

vg:GameResource a owl:Class ;
    rdfs:label "Game Resource"@en ;
    rdfs:comment "A domain resource representing a video game, a particular game release, or an extension; modeled as a PROV entity so derivation provenance can be reused directly."@en ;
    owl:disjointWith vg:Genre,
        vg:Review .

vg:InputDevice a owl:Class ;
    rdfs:label "Input Device"@en ;
    rdfs:comment "A device used to provide input to a game or gameplay session."@en ;
    rdfs:subClassOf vg:Device .

vg:Platform a owl:Class ;
    rdfs:label "Platform"@en ;
    rdfs:comment "A hardware, software, browser, mobile, cloud, or virtual-reality platform on which games may run."@en ;
    owl:disjointWith vg:VideoGame .

vg:GameRelease a owl:Class ;
    rdfs:label "Game Release"@en ;
    rdfs:comment "A particular release, edition, or version of a VideoGame. Every GameRelease is related to at least one VideoGame through :releaseOf; use dcterms:title and dcterms:identifier for generic metadata, schema:version for version text, and :releaseDate for its formal release date."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty vg:usesMediaFormat ;
            owl:someValuesFrom vg:MediaFormat ],
        [ a owl:Restriction ;
            owl:onProperty vg:supportsOutputDevice ;
            owl:someValuesFrom vg:OutputDevice ],
        [ a owl:Restriction ;
            owl:onProperty vg:supportsInputDevice ;
            owl:someValuesFrom vg:InputDevice ],
        [ a owl:Restriction ;
            owl:onProperty vg:availableOnPlatform ;
            owl:someValuesFrom vg:Platform ],
        [ a owl:Restriction ;
            owl:onProperty vg:releaseOf ;
            owl:someValuesFrom vg:VideoGame ],
        vg:GameResource ;
    owl:disjointWith vg:VideoGame .

vg:VideoGame a owl:Class ;
    rdfs:label "Video Game"@en ;
    rdfs:comment "A video game considered as a creative work independent of a particular release."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty vg:supportsOutputDevice ;
            owl:someValuesFrom vg:OutputDevice ],
        [ a owl:Restriction ;
            owl:onProperty vg:supportsInputDevice ;
            owl:someValuesFrom vg:InputDevice ],
        [ a owl:Restriction ;
            owl:minQualifiedCardinality "1"^^xsd:nonNegativeInteger ;
            owl:onClass vg:Platform ;
            owl:onProperty vg:intendedForPlatform ] .
